const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){ statusMessage.textContent=message; clearTimeout(toastTimer); toastTimer=setTimeout(()=>statusMessage.textContent='',6000); }
function heading(title, description){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><span class="page-meta">Ukázkový stav · 28. 10. 2026</span></div>`;}
function notice(){return '<div class="notice"><strong>Data nejsou načtená z produkce.</strong>Tento návrh ukazuje uspořádání a chování. Počty, hráči i případy níže jsou ukázkové.</div>';}
function sourceList(){return '<div class="source-list"><div class="source-line"><span>Herní výsledky<small>Autoritativní zdroj výsledků a postupu</small></span><span class="badge">Nepřipojeno</span></div><div class="source-line"><span>Produktová analytika<small>Pokrytí událostí dosud neověřeno</small></span><span class="badge warning">Neověřené měření</span></div><div class="source-line"><span>Hlášení a podpora<small>Stav jednotlivých případů</small></span><span class="badge">Ukázková data</span></div><div class="source-line"><span>Provozní diagnostika<small>Krátce opakované registrace, push</small></span><span class="badge">Nepřipojeno</span></div></div>';}
function overview(){return heading('Co potřebuje pozornost','Jedno místo pro dnešní provoz, hráčskou podporu a stav hry.')+notice()+`<div class="summary-grid"><div><b>4</b><span>otevřená hlášení</span><small>Ukázka · 2 technická, 2 slovní</small></div><div><b>1</b><span>účet k prověření</span><small>Ukázka · více stejných jmen</small></div><div><b>—</b><span>aktivních hráčů dnes</span><small>Zdroj není připojený</small></div></div><div class="split"><section class="section"><div class="section-head"><div><h2>Vyřešit jako první</h2><p>Konkrétní případy s jasným dalším krokem.</p></div></div><div class="task-row"><div><strong>Klára: najít správný účet</strong><small>3 shodná jména, odlišný postup a tým</small></div><button data-go="players">Porovnat účty</button></div><div class="task-row"><div><strong>Hlášení chyby přihlášení</strong><small>Ukázkový případ SUP-204 · před 2 h</small></div><button data-go="reports">Otevřít případ</button></div><div class="task-row"><div><strong>Prověřit měření prvních kroků</strong><small>Launch používá starší kohortu board-v2</small></div><button data-go="analytics">Zobrazit stav</button></div></section><section class="section"><h2>Odkud jsou čísla</h2>${sourceList()}</section></div><section class="section"><h2>Hra dnes</h2><div class="row"><span class="badge">Denní výzva</span><span class="badge">Extra výzva</span><span class="badge">Volná hra</span><span class="badge">Tajenka</span></div><p class="footer-note">Dostupnost se v implementaci načte z aktuálního runtime. Ukázka neurčuje, které režimy jsou právě aktivní.</p><div class="task-row"><div><strong>Měsíční soutěž</strong><small>Samostatná připravovaná větev. Zde ji nepovažujeme za nasazenou funkci.</small></div><span class="badge info">Pouze preview</span></div></section>`;}
function playersPage(){return heading('Hráči a týmy','Najdi konkrétní identitu, porovnej postup a připrav bezpečný krok podpory.')+notice()+`<section class="section"><div class="toolbar"><div class="field grow"><label for="playerSearch">Jméno, ID nebo tým</label><input id="playerSearch" type="search" placeholder="Například Klára" value="Klára"></div><div class="field"><label for="playerState">Aktivita</label><select id="playerState"><option value="all">Všechny účty</option><option value="active">Aktivní dnes</option><option value="old">Starší účty</option></select></div></div><p class="filters-note" id="playerCount">3 ukázkové účty · stejné jméno neznamená stejný účet</p><div class="table-wrap"><table class="players-table"><thead><tr><th>Hráč / stabilní ID</th><th>XP celkem</th><th>Výsledky</th><th>Poslední aktivita</th><th>Tým</th><th></th></tr></thead><tbody id="playersBody"></tbody></table></div></section><section class="section"><h2>Oprava týmové identity</h2><p>Při záměně starého a používaného účtu nejdřív porovnat poslední aktivitu, výsledky a propojení přihlášení. Účty se neslučují podle jména.</p><span class="badge info">Návrh druhé etapy</span><p class="footer-note">Plán opravy má samostatně ukázat členství v týmu a případné zpětné přiřazení výsledků. Tento náhled nic nepřepisuje.</p><button id="teamPreview" type="button">Prohlédnout návrh kontroly dopadu</button><div id="teamImpact" class="recovery-preview" hidden><h3>Nejprve porovnat dvě identity</h3><p>Aktivní účet <code>demo-player-101</code> → cílový tým Papírové lišky.<br>Starší účet <code>demo-player-102</code> → samostatný hráč.</p><p>Rozsah výsledků: pouze výslovně vybraný týden. Osobní XP a historická období mají zůstat zachovaná.</p><p><strong>Před realizací je nutné ověřit vlastnictví účtu, kolize, dotčené řádky a aktuální stav.</strong> PR 118 tuto týmovou opravu nepřidává.</p><span class="badge">Čtení / návrh · bez zápisu</span></div></section>`;}
const reports = [
 {id:'SUP-204',type:'technická',title:'Po přihlášení vidím starší postup',status:'Nové',age:'před 2 h',body:'Ukázkové hlášení. Porovnat identitu a poslední potvrzené výsledky před jakoukoli obnovou.'},
 {id:'WORD-82',type:'slovní',title:'Podezření na chybu slova',status:'Prověřuji',age:'včera',body:'Ukázkové hlášení k desce demo-g6-d-042. Zobrazit přesné zadání a historickou verzi desky.'},
 {id:'SUP-203',type:'technická',title:'Obnova přístupu ke starému účtu',status:'Prověřuji',age:'včera',body:'Ukázkový případ. Vybrat stabilní player_id, ověřit kolizi e-mailu a připravit obnovu.'},
 {id:'WORD-81',type:'slovní',title:'Nejasná nápověda na desce',status:'Nové',age:'před 2 dny',body:'Ukázkový případ. Vyřízení hlášení a publikace opravy obsahu jsou dvě různé akce.'},
 {id:'SUP-190',type:'technická',title:'Starší problém s načítáním',status:'Vyřešeno',age:'před týdnem',body:'Ukázkový uzavřený případ zůstává dohledatelný v archivu.'}
];
function reportsPage(){return heading('Hlášení','Technické potíže i hlášení slov v jedné dohledatelné frontě.')+notice()+`<section class="section"><div class="toolbar"><div class="field grow"><label for="reportSearch">Hledat v případech</label><input id="reportSearch" type="search" placeholder="ID případu, text nebo slovo"></div><div class="field"><label for="reportType">Typ</label><select id="reportType"><option value="all">Všechny typy</option><option value="technická">Technická podpora</option><option value="slovní">Slova a desky</option></select></div><div class="field"><label for="reportStatus">Stav</label><select id="reportStatus"><option value="open">Otevřená</option><option value="all">Včetně archivu</option><option value="Vyřešeno">Vyřešená</option></select></div></div><div id="reportRows"></div></section>`;}
function contentPage(){return heading('Obsah a kvalita','Zkontroluj dostupnost výzev a desky, které hráčům dělají potíže.')+notice()+`<section class="section"><div class="section-head"><div><h2>Kalendář výzev</h2><p>Ukázka kontroly návaznosti obsahu; nejde o živý rozpis.</p></div><span class="badge">28.–30. října 2026</span></div><div class="table-wrap"><table><thead><tr><th>Datum</th><th>Denní výzva</th><th>Extra</th><th>Kontrola</th></tr></thead><tbody><tr><td>Dnes · 28. 10.</td><td>Ukázková deska A</td><td>Ukázková deska B</td><td>Bez živého ověření</td></tr><tr><td>Zítra · 29. 10.</td><td>Ukázková deska C</td><td>Ukázková deska D</td><td>Bez živého ověření</td></tr><tr><td>30. 10.</td><td>—</td><td>—</td><td>Zdroj nepřipojen</td></tr></tbody></table></div></section><section class="section"><h2>Obtížnost a hlášení desek</h2><div class="notice warning"><strong>Vždy ukázat rozsah a vzorek.</strong>Současný přehled kvality používá první celoživotní pokusy v dostupném 90denním okně. Historie může být omezená.</div><div class="toolbar"><div class="field"><label for="qualityDifficulty">Obtížnost</label><select id="qualityDifficulty"><option>Všechny obtížnosti</option><option>Snadná</option><option>Střední</option><option>Těžká</option><option>Mozkožrout</option></select></div></div><div id="qualityDemo"><div class="task-row"><div><strong>demo-g6-d-042</strong><small>Ukázka · 12 prvních pokusů · 2 hlášení</small></div><span class="badge warning">Malý vzorek</span></div><p class="footer-note">Příznak obtížnosti je podnět k prověření. Stav „vyřešeno“ u hlášení sám o sobě nepublikuje opravu desky.</p></div></section>`;}
function operationsPage(){return heading('Provoz','Stav služeb, diagnostika registrací a doručování bez schovaných technických překvapení.')+notice()+`<div class="split"><section class="section"><h2>Prostředí a verze</h2><dl class="definition-list"><div><dt>Režim tohoto náhledu</dt><dd>Lokální, bez API</dd></div><div><dt>Produkční SHA při auditu</dt><dd><code>1de7389</code></dd></div><div><dt>Aktuálnost produkčního stavu</dt><dd>Nyní neověřováno</dd></div><div><dt>Databáze</dt><dd>Nepřipojena</dd></div></dl><p class="footer-note">Implementace má zobrazit skutečné prostředí, SHA, datum získání a stav každého zdroje. Nepoužívá zelenou tečku za chybějící data.</p></section><section class="section"><h2>Diagnostika</h2><div class="task-row"><div><strong>Krátce opakované registrace</strong><small>account-integrity: nové účty v intervalu ≤ 10 s. Nejde o úplný detektor duplicit.</small></div><span class="badge">Pouze čtení</span></div><div class="task-row"><div><strong>Push doručování</strong><small>Přehled zařízení, výsledků a poslední chyby</small></div><span class="badge">Pouze čtení</span></div><div class="task-row"><div><strong>Dnešní obsah a plánování</strong><small>Poslední úspěch, chyba a čas očekávaného běhu</small></div><span class="badge">Nutné doplnit zdroj</span></div></section></div><section class="section"><h2>Schopnosti aktuálního vydání</h2><div class="source-list"><div class="source-line"><span>Obnova starého účtu<small>PR 118, otevřený draft</small></span><span class="badge warning">Dosud nezačleněno</span></div><div class="source-line"><span>Měsíční soutěž<small>Samostatné preview, nepovažovat za produkci</small></span><span class="badge info">Pouze preview</span></div><div class="source-line"><span>Archiv a zvláštní režimy<small>Dostupnost odvodit ze skutečné konfigurace</small></span><span class="badge">Neověřeno</span></div></div></section>`;}
function analyticsPage(){return heading('Analytika','Měření současné hry s vysvětlením, koho a jak přesně počítáme.')+`<div class="notice warning"><strong>Neověřené měření</strong>Dosavadní Launch filtruje board-v2, současné první kroky používají board-v3-short. Nový funnel vyžaduje ověření událostí a kohorty.</div><div class="toolbar"><div class="field"><label for="analyticsPeriod">Období v Europe/Prague</label><select id="analyticsPeriod"><option>Posledních 7 dní</option><option>Posledních 28 dní</option></select></div><span class="badge">Ukázka · žádná živá statistika</span></div><div class="split"><section class="section"><h2>Od krátkého tréninku k uložené hře</h2><div class="funnel"><div><span><b>Otevření krátkého tréninku</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div><div><span><b>Dokončení tréninku</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div><div><span><b>Start první skutečné volné hry</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div><div><span><b>Dokončení první hry</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div><div><span><b>Nabídka uložení</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div><div><span><b>Dokončená autentizace</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div><div><span><b>Serverem potvrzené uložení</b><small>Událost a pokrytí neověřeno</small></span><strong>—</strong></div></div><p class="footer-note">Přeskočení tréninku má samostatnou větev. Pomlčka znamená nedostupný nebo neověřený údaj, nikoli nulu hráčů.</p></section><section class="section"><h2>Kvalita měření</h2><dl class="definition-list"><div><dt>Aktuální onboarding</dt><dd>board-v3-short</dd></div><div><dt>Dosavadní Launch kohorta</dt><dd>board-v2</dd></div><div><dt>Pokrytí událostí</dt><dd>Dosud neověřeno</dd></div><div><dt>Kohorta první návštěvy</dt><dd>Měřitelnost nedoložena</dd></div></dl><p class="footer-note">První návštěva zatím není doloženou měřitelnou kohortou. D1/D7 počítat jen z dostatečně starých kohort. Registrované hráče, anonymní návštěvy a výsledky nevydávat za stejný základ.</p></section></div><section class="section"><h2>Historická měření</h2><details><summary>Starší Launch / board-v2</summary><p class="footer-note">Historická kohorta zůstává dohledatelná s původní definicí. Nepoužívá se jako výchozí pohled na dnešní onboarding.</p></details></section>`;}
function auditPage(){return heading('Historie zásahů','U každé změny dohledat cíl, důvod, výsledek a provádějícího vlastníka.')+notice()+`<section class="section"><div class="toolbar"><div class="field grow"><label for="auditSearch">Cíl nebo typ zásahu</label><input id="auditSearch" type="search" placeholder="Například demo-player-102"></div></div><div id="auditRows"><article class="timeline-item" data-audit="obnova recovery demo-player-102"><div class="row"><strong>Připravena obnova e-mailu</strong><span class="badge info">Čeká na ověření hráčem</span></div><p>Ukázkový záznam · vlastník · 28. 10. 2026, 16:20</p><dl class="event-details"><dt>Cíl</dt><dd><code>demo-player-102</code></dd><dt>Adresa</dt><dd>k••••@example.com</dd><dt>Důvod</dt><dd>Potvrzený požadavek hráče na obnovení přístupu</dd><dt>Výsledek</dt><dd>Požadavek připraven. K ověření e-mailu zatím nedošlo.</dd></dl></article><article class="timeline-item" data-audit="hlášení WORD-81"><div class="row"><strong>Změněn stav hlášení</strong><span class="badge">Nové → Prověřuji</span></div><p>Ukázkový záznam · vlastník · 28. 10. 2026, 15:10</p><dl class="event-details"><dt>Cíl</dt><dd>WORD-81</dd><dt>Důvod</dt><dd>Prověřit formulaci nápovědy proti verzi desky</dd><dt>Výsledek</dt><dd>Interní poznámka uložena; obsah hry se nezměnil.</dd></dl></article></div></section>`;}
const views={overview,players:playersPage,reports:reportsPage,content:contentPage,operations:operationsPage,analytics:analyticsPage,audit:auditPage};
function render(view){selectedView=view in views?view:'overview'; main.innerHTML=views[selectedView](); document.querySelectorAll('[data-view]').forEach(button=>button.toggleAttribute('aria-current',false)); document.querySelector(`[data-view="${selectedView}"]`).setAttribute('aria-current','page'); main.querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>render(button.dataset.go)); bindView();}
function renderPlayers(){const query=document.getElementById('playerSearch').value.trim().toLocaleLowerCase('cs');const filter=document.getElementById('playerState').value;const rows=players.filter(p=>`${p.name} ${p.id} ${p.team}`.toLocaleLowerCase('cs').includes(query)&&(filter==='all'||(filter==='active'&&p.current)||(filter==='old'&&!p.current)));document.getElementById('playerCount').textContent=`${rows.length} ukázkové účty · stejné jméno neznamená stejný účet`;document.getElementById('playersBody').innerHTML=rows.map(p=>`<tr><td><button class="text-button" data-player="${p.id}">${p.name}</button><small>${p.id}${p.current?' · aktivní dnes':''}</small></td><td data-label="XP celkem" class="numeric">${p.xp}</td><td data-label="Výsledky" class="numeric">${p.completed}</td><td data-label="Poslední aktivita">${p.last}</td><td data-label="Tým">${p.team}</td><td><button data-player="${p.id}">Detail účtu</button></td></tr>`).join('')||'<tr><td colspan="6">Žádný ukázkový účet neodpovídá hledání.</td></tr>';document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>openPlayer(b.dataset.player));}
function openPlayer(id){const p=players.find(p=>p.id===id);document.getElementById('playerDialogContent').innerHTML=`<div class="dialog-inner"><div class="dialog-head"><div><h2 id="playerDialogTitle">${p.name}</h2><p>${p.id} · ukázkový účet</p></div><button class="dialog-close" id="closeDialog">Zavřít</button></div><div class="summary-grid"><div><b>${p.xp}</b><span>XP celkem</span></div><div><b>${p.completed}</b><span>výsledků</span></div><div><b>${p.current?'Dnes':'Starší'}</b><span>poslední aktivita</span></div></div><dl class="definition-list"><div><dt>Tým</dt><dd>${p.team}</dd></div><div><dt>Poslední aktivita</dt><dd>${p.last}</dd></div><div><dt>Přihlášení</dt><dd>${p.login}</dd></div><div><dt>E-mail</dt><dd>${p.email||'Není připojen'}</dd></div><div><dt>Postup</dt><dd>${p.progress}</dd></div><div><dt>Účet vytvořen</dt><dd>${p.created}</dd></div></dl><section class="dialog-section"><div class="row"><h3>Obnova přístupu</h3><span class="badge info">Návrh integrace PR 118</span></div><p class="muted">Obnova se připraví pro tento konkrétní účet. E-mail se ověří až kliknutím hráče na odkaz.</p><form id="recoveryForm"><div class="field"><label for="recoveryEmail">E-mail pro obnovu</label><input id="recoveryEmail" type="email" autocomplete="off" required placeholder="klara@example.com"></div><div class="field"><label for="recoveryReason">Interní důvod</label><textarea id="recoveryReason" required placeholder="Podle čeho je ověřený správný účet a požadavek hráče?"></textarea></div><p class="footer-note">Už ověřený e-mail jiného účtu nelze převzít. Starší nevyřízený požadavek se při nové obnově zneplatní.</p><button class="primary" type="submit">Připravit obnovu</button></form><div id="recoveryImpact" class="recovery-preview" hidden aria-live="polite"></div></section><section class="dialog-section"><h3>Diagnostika účtu</h3><p class="muted">Diagnostika account-integrity zachytí krátký burst registrací v intervalu ≤ 10 s. Nekontroluje integritu výsledků ani všechny duplicitní účty. Stav push zařízení je samostatný přehled pro čtení. Data tohoto ukázkového účtu nejsou načtena.</p><span class="badge">Zdroj nepřipojen</span></section></div>`;document.getElementById('closeDialog').onclick=()=>dialog.close();document.getElementById('recoveryForm').onsubmit=event=>{event.preventDefault();const email=document.getElementById('recoveryEmail').value;const parts=email.split('@');const mask=parts[0].slice(0,1)+'••••@'+parts[1];const impact=document.getElementById('recoveryImpact');impact.innerHTML=`<h3>Náhled dopadu obnovy</h3><dl class="event-details"><dt>Vybraný účet</dt><dd><code>${p.id}</code></dd><dt>Adresa</dt><dd>${esc(mask)}</dd><dt>Herní postup</dt><dd>${p.xp} XP a ${p.completed} výsledků zůstává na tomto účtu.</dd></dl><ol><li>Server znovu ověří oprávnění vlastníka a kolizi adresy.</li><li>Připraví požadavek pro zvolený účet a odešle ověřovací odkaz.</li><li>Teprve ověření schránky hráčem může připojit e-mail.</li></ol><strong>Tady se nic neodeslalo ani nezměnilo.</strong><p class="footer-note">V implementaci následuje samostatné potvrzení odeslání a audit výsledku. Tento prototyp končí u náhledu.</p>`;impact.hidden=false;impact.scrollIntoView({block:'nearest',behavior:'instant'});};dialog.showModal();}
function renderReports(){const q=document.getElementById('reportSearch').value.toLocaleLowerCase('cs');const type=document.getElementById('reportType').value;const status=document.getElementById('reportStatus').value;const rows=reports.filter(r=>(type==='all'||r.type===type)&&(status==='all'||(status==='open'&&r.status!=='Vyřešeno')||status===r.status)&&`${r.id} ${r.title}`.toLocaleLowerCase('cs').includes(q));document.getElementById('reportRows').innerHTML=rows.map(r=>`<article class="task-row"><div><div class="row"><strong>${r.title}</strong><span class="badge">${r.status}</span></div><small>${r.id} · ${r.type} · ${r.age}</small><details><summary>Podrobnosti případu</summary><p class="footer-note">${r.body}</p><p class="footer-note">Případ zůstává dohledatelný po vyřízení. Odesílání odpovědí hráči není součástí tohoto prototypu.</p></details></div></article>`).join('')||'<p class="empty">Tomuto filtru neodpovídá žádný ukázkový případ.</p>';}
function bindView(){if(selectedView==='players'){renderPlayers();document.getElementById('playerSearch').oninput=renderPlayers;document.getElementById('playerState').onchange=renderPlayers;document.getElementById('teamPreview').onclick=()=>{const panel=document.getElementById('teamImpact');panel.hidden=!panel.hidden;};}if(selectedView==='reports'){renderReports();['reportSearch','reportType','reportStatus'].forEach(id=>document.getElementById(id).addEventListener(id==='reportSearch'?'input':'change',renderReports));}if(selectedView==='content'){document.getElementById('qualityDifficulty').onchange=e=>{document.getElementById('qualityDemo').hidden=e.target.selectedIndex>0;toast('Filtr změněn pouze nad ukázkou. Živá data nejsou připojena.');};}if(selectedView==='analytics'){document.getElementById('analyticsPeriod').onchange=()=>toast('Období změněno. Metriky zůstávají neověřené a bez hodnot.');}if(selectedView==='audit'){document.getElementById('auditSearch').oninput=e=>document.querySelectorAll('[data-audit]').forEach(row=>row.hidden=!row.dataset.audit.toLocaleLowerCase('cs').includes(e.target.value.toLocaleLowerCase('cs')));}}
document.getElementById('navigation').addEventListener('click',e=>{const button=e.target.closest('[data-view]');if(button)render(button.dataset.view);});
document.querySelector('.brand').onclick=e=>{e.preventDefault();render('overview');};
document.getElementById('themeToggle').onclick=e=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';e.currentTarget.textContent=dark?'Světlý vzhled':'Tmavý vzhled';e.currentTarget.setAttribute('aria-pressed',String(dark));};
render('overview');
